import{_ as e,o,c as r,ag as n}from"./chunks/framework.BZohXCq9.js";const p=JSON.parse('{"title":"Complete Local Testing Checklist – Handover to Client","description":"","frontmatter":{},"headers":[],"relativePath":"TESTING_CHECKLIST_HANDOVER.md","filePath":"TESTING_CHECKLIST_HANDOVER.md"}'),d={name:"TESTING_CHECKLIST_HANDOVER.md"};function s(a,t,i,c,l,g){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="complete-local-testing-checklist-–-handover-to-client" tabindex="-1">Complete Local Testing Checklist – Handover to Client <a class="header-anchor" href="#complete-local-testing-checklist-–-handover-to-client" aria-label="Permalink to &quot;Complete Local Testing Checklist – Handover to Client&quot;">​</a></h1><p>Use this document to test <strong>every flow and edge case</strong> on localhost before handing over to the client. Tick each item as you complete it.</p><hr><h2 id="prerequisites-do-once" tabindex="-1">Prerequisites (do once) <a class="header-anchor" href="#prerequisites-do-once" aria-label="Permalink to &quot;Prerequisites (do once)&quot;">​</a></h2><ul><li><p>[ ] <strong>Environment</strong></p><ul><li>[ ] <code>server/.env</code> has <code>STRIPE_SECRET_KEY=sk_test_...</code> and <code>STRIPE_WEBHOOK_SECRET=whsec_...</code></li><li>[ ] <code>Frontend/.env</code> has <code>VITE_STRIPE_PUBLISHABLE_KEY=pk_test_...</code></li><li>[ ] MongoDB running; server and frontend start without errors</li></ul></li><li><p>[ ] <strong>Stripe CLI for webhooks</strong></p><ul><li>[ ] Stripe CLI installed (<code>stripe --version</code>)</li><li>[ ] Logged in: <code>stripe login</code></li><li>[ ] In a <strong>separate terminal</strong>: <code>stripe listen --forward-to http://localhost:4000/webhooks/stripe</code></li><li>[ ] Copy the <code>whsec_...</code> into <code>server/.env</code> as <code>STRIPE_WEBHOOK_SECRET</code>, restart server</li><li>[ ] Keep <code>stripe listen</code> running for the whole test session</li></ul></li><li><p>[ ] <strong>Test users</strong></p><ul><li>[ ] At least one <strong>Admin</strong>, one <strong>Instructor</strong>, one <strong>Student</strong> (with email) that you can log in as</li></ul></li></ul><hr><h2 id="stripe-test-cards-reference" tabindex="-1">Stripe test cards (reference) <a class="header-anchor" href="#stripe-test-cards-reference" aria-label="Permalink to &quot;Stripe test cards (reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Card number</th><th>Expiry</th><th>CVC</th></tr></thead><tbody><tr><td>Success</td><td>4242 4242 4242 4242</td><td>Any future (e.g. 12/34)</td><td>Any 3 digits</td></tr><tr><td>3DS required (succeeds after auth)</td><td>4000 0000 0000 3220</td><td>Any future</td><td>Any 3 digits</td></tr><tr><td>Declined (generic)</td><td>4000 0000 0000 0002</td><td>Any future</td><td>Any 3 digits</td></tr><tr><td>Insufficient funds</td><td>4000 0000 0000 9995</td><td>Any future</td><td>Any 3 digits</td></tr><tr><td>Funds available immediately (payout test)</td><td>4000 0000 0000 0077</td><td>Any future</td><td>Any 3 digits</td></tr></tbody></table><p>Use these <strong>only</strong> in Stripe Checkout / payment forms (test mode). Do not use real cards.</p><hr><h2 id="_1-instructor-–-stripe-connect-payment-readiness" tabindex="-1">1. Instructor – Stripe Connect &amp; payment readiness <a class="header-anchor" href="#_1-instructor-–-stripe-connect-payment-readiness" aria-label="Permalink to &quot;1. Instructor – Stripe Connect &amp; payment readiness&quot;">​</a></h2><h3 id="_1-a-–-happy-path" tabindex="-1">1.A – Happy path <a class="header-anchor" href="#_1-a-–-happy-path" aria-label="Permalink to &quot;1.A – Happy path&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>1.1</td><td>Start Stripe onboarding</td><td>As <strong>Instructor</strong>, go to <strong>Settings → Payment Management</strong>. Click “Connect with Stripe” / “Start payment setup”.</td><td>Redirected to Stripe; complete identity/bank (use test data). Return to app.</td><td></td></tr><tr><td>1.2</td><td>Return URL &amp; verify</td><td>After completing onboarding on Stripe, you are redirected to <code>/payment/complete</code>. Page calls <strong>Verify</strong>.</td><td>Status shows “verified” / “Payments enabled” when Stripe has activated the account.</td><td></td></tr><tr><td>1.3</td><td>Payment-ready blocks booking</td><td>As <strong>Student</strong>, find an instructor who has <strong>not</strong> completed Stripe. Try to book.</td><td>Error or “Not available for payment” / “Complete Stripe setup”.</td><td></td></tr><tr><td>1.4</td><td>Payment-ready allows booking</td><td>As <strong>Student</strong>, book with an instructor who <strong>has</strong> completed Stripe.</td><td>Can proceed to checkout (instant or setup).</td><td></td></tr></tbody></table><h3 id="_1-b-–-instructor-onboarding-edge-cases" tabindex="-1">1.B – Instructor onboarding edge cases <a class="header-anchor" href="#_1-b-–-instructor-onboarding-edge-cases" aria-label="Permalink to &quot;1.B – Instructor onboarding edge cases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>1.5</td><td>Incomplete onboarding – “Continue setup”</td><td>As <strong>Instructor</strong>, start onboarding (get Stripe link) then <strong>close the tab</strong> without submitting. Go back to <strong>Settings → Payment Management</strong>.</td><td>Status “Setup in progress”. Button <strong>“Continue setup”</strong> (or similar) is shown.</td><td></td></tr><tr><td>1.6</td><td>Continue setup opens Stripe again</td><td>Click <strong>“Continue setup”</strong>.</td><td>New Stripe onboarding URL opens; you can complete or add details.</td><td></td></tr><tr><td>1.7</td><td>Stripe restricted/rejected – we show it</td><td>When Stripe <strong>restricts</strong> or <strong>rejects</strong> the account (e.g. more info needed, verification failed), our app gets this via <strong>Verify</strong> or webhook <code>account.updated</code>. Instructor goes to <strong>Settings → Payment Management</strong>.</td><td>Status shows <strong>“Action required”</strong> / <strong>“Stripe: Action required”</strong>. Message like “Stripe needs additional information or has temporarily restricted your account. Resume onboarding to fix this.”</td><td></td></tr><tr><td>1.8</td><td>Fix now – open Stripe again after reject</td><td>With status <strong>restricted</strong> (or <strong>disabled</strong>), click <strong>“Fix now in Stripe”</strong> / <strong>“Resume onboarding”</strong>.</td><td>A <strong>new Stripe onboarding link</strong> opens; instructor can fix details and resubmit. (Backend allows a new link when account is not yet verified.)</td><td></td></tr><tr><td>1.9</td><td>After return from Stripe (complete page)</td><td>Complete onboarding on Stripe; land on <strong>/payment/complete</strong>. Page runs <strong>Verify</strong>. If status is <strong>restricted</strong>, page shows “Action required in Stripe” and button <strong>“Fix now in Stripe”</strong>.</td><td>Clicking <strong>“Fix now in Stripe”</strong> opens a new Stripe link so they can fix and try again.</td><td></td></tr><tr><td>1.10</td><td>Regenerate link (optional)</td><td>As <strong>Instructor</strong>, before finishing onboarding (status “Setup in progress”), use <strong>“Continue setup”</strong>. Or, if shown, any “Regenerate onboarding link” action.</td><td>New Stripe onboarding URL works and you can complete from there. (Test 1.6 covers this.)</td><td></td></tr></tbody></table><p><strong>Note:</strong> When Stripe rejects or restricts onboarding, we <strong>do</strong> show that to the user (restricted/disabled state and message) and we <strong>do</strong> allow them to try again: <strong>“Fix now in Stripe”</strong> / <strong>“Continue setup”</strong> calls the backend to get a new Stripe account link so they can complete or correct onboarding.</p><hr><h2 id="_2-student-–-instant-payment-lesson-≤48h-away" tabindex="-1">2. Student – Instant payment (lesson ≤48h away) <a class="header-anchor" href="#_2-student-–-instant-payment-lesson-≤48h-away" aria-label="Permalink to &quot;2. Student – Instant payment (lesson ≤48h away)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>2.1</td><td>Instant checkout</td><td>Create <strong>instructor availability</strong> for a time <strong>within 48 hours</strong> from now. As <strong>Student</strong>, book that slot and go to checkout.</td><td>Server log: <code>INSTANT (payment now)</code>. Redirect to Stripe <strong>Checkout</strong> with <strong>payment</strong> (not setup).</td><td></td></tr><tr><td>2.2</td><td>Pay with success card</td><td>On Stripe Checkout use <strong>4242 4242 4242 4242</strong>. Complete payment.</td><td>Redirect back with <code>?checkout=success&amp;session_id=...</code>. Booking confirmed; all slots <strong>paid</strong>. No T-48 charge for this booking.</td><td></td></tr><tr><td>2.3</td><td>Pay with 3DS card</td><td>Book again (instant). On Checkout use <strong>4000 0000 0000 3220</strong>. Complete 3DS step on Stripe’s page.</td><td>After 3DS, redirect back; booking confirmed; slots paid.</td><td></td></tr><tr><td>2.4</td><td>Declined card</td><td>Book again (instant). On Checkout use <strong>4000 0000 0000 0002</strong>.</td><td>Stripe shows error on same page; user can try another card or click Back. If they click Back they hit cancel_url (same as 2.5). Booking stays pending; toast “Payment was cancelled” and link to Book lesson to retry.</td><td></td></tr><tr><td>2.5</td><td>Cancel checkout</td><td>Start instant checkout; on Stripe page click “Back” or cancel.</td><td>Redirect to <code>.../booking-details?checkout=cancelled</code>. Toast “Payment was cancelled”; if state was lost (redirect), page shows message + “Go to Book lesson” to retry. Booking stays pending.</td><td></td></tr></tbody></table><hr><h2 id="_3-student-–-deferred-payment-lesson-48h-away-t-48-charge" tabindex="-1">3. Student – Deferred payment (lesson &gt;48h away) + T-48 charge <a class="header-anchor" href="#_3-student-–-deferred-payment-lesson-48h-away-t-48-charge" aria-label="Permalink to &quot;3. Student – Deferred payment (lesson &gt;48h away) + T-48 charge&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>3.1</td><td>Deferred checkout (setup only)</td><td>Create availability for a time <strong>more than 48 hours</strong> from now. As <strong>Student</strong>, book and go to checkout.</td><td>Server log: <code>DEFERRED (setup mode, charge at T-48)</code>. Stripe Checkout in <strong>setup</strong> mode – <strong>no charge</strong>, only save card.</td><td></td></tr><tr><td>3.2</td><td>Save card and return</td><td>Complete Stripe setup (e.g. 4242 4242 4242 4242).</td><td>Redirect with <code>?checkout=setup_success&amp;session_id=...</code>. Booking confirmed; slots <strong>pending_payment</strong>.</td><td></td></tr><tr><td>3.3</td><td>T-48 job charges (quick test)</td><td><strong>Optional:</strong> In <code>server/src/jobs/t48ChargeJob.js</code> temporarily set <code>FORTY_EIGHT_HOURS_MS = 2 * 60 * 1000</code> (2 min). Create a deferred booking for a lesson that starts in <strong>&gt;2 min</strong>. Wait 2+ min; wait for next T-48 job run (every 5 min by default, or trigger if you have a way).</td><td>Server log: <code>[T48ChargeJob] Charging slot ... for booking ...</code> then <code>payment succeeded</code> and <code>Done. charged=1</code>. Slot becomes <strong>paid</strong>. <strong>Revert</strong> the constant after test.</td><td></td></tr><tr><td>3.4</td><td>T-48 with 3DS</td><td>With same short window, use a <strong>3DS card</strong> (4000 0000 0000 3220) when saving card in setup. When T-48 runs, it will get <code>requires_action</code>.</td><td>Slot set to <strong>requires_action</strong>; email “Action required: complete payment”. In <strong>Booked lessons</strong>, “Complete payment” appears for that slot.</td><td></td></tr><tr><td>3.5</td><td>Complete T-48 3DS payment</td><td>Click “Complete payment” for a slot in <strong>requires_action</strong>. Complete 3DS in the flow.</td><td>Slot moves to <strong>paid</strong>; booking confirmed when all slots paid.</td><td></td></tr><tr><td>3.6</td><td>T-48 declined card</td><td>Use <strong>4000 0000 0000 0002</strong> when saving card (setup). When T-48 runs.</td><td>Slot set to <strong>payment_failed</strong> (after retries). No charge.</td><td></td></tr><tr><td>3.7</td><td>Webhook completes deferred without frontend</td><td>Start deferred checkout; complete setup on Stripe; <strong>close browser before</strong> your app’s success page loads.</td><td>Webhook <code>checkout.session.completed</code> should still save <code>stripeCustomerId</code> and payment method on booking. Next T-48 run can charge (verify with 3.3-style test).</td><td></td></tr></tbody></table><hr><h2 id="_4-lesson-status-payout-eligibility" tabindex="-1">4. Lesson status &amp; payout eligibility <a class="header-anchor" href="#_4-lesson-status-payout-eligibility" aria-label="Permalink to &quot;4. Lesson status &amp; payout eligibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>4.1</td><td>Mark lesson completed</td><td>As <strong>Instructor</strong> (or Admin), open the booking and mark a <strong>paid</strong> slot as <strong>Completed</strong>.</td><td>Slot <code>lessonStatus</code> = completed; for paid slots, <code>payoutStatus</code> becomes <strong>pending</strong> and <code>payoutEligibleAt</code> set (e.g. now + 1 min in your config).</td><td></td></tr><tr><td>4.2</td><td>Mark lesson cancelled</td><td>As <strong>Student</strong> or <strong>Instructor</strong>, cancel one slot of a booking.</td><td>Slot status <strong>cancelled</strong>; booking becomes semi_cancelled or cancelled if all cancelled. Availability freed.</td><td></td></tr><tr><td>4.3</td><td>Mark lesson missed</td><td>As <strong>Instructor</strong>, mark a slot as <strong>Missed</strong> (if UI exists).</td><td>Slot status <strong>missed</strong>; no refund; availability/booking state consistent.</td><td></td></tr><tr><td>4.4</td><td>Payout job runs</td><td>After marking a paid slot <strong>completed</strong>, wait for payout delay (e.g. 1 min). Wait for payout job (e.g. every 1 min in index.js). Check server log.</td><td><code>[PayoutJob] Done. processed=1</code>. Slot <code>payoutStatus</code> = <strong>completed</strong>; <code>payoutId</code> set. Transaction with type <strong>payout</strong> and <strong>stripePayoutId</strong> created.</td><td></td></tr><tr><td>4.5</td><td>Refund blocked after payout</td><td>If a slot already has <code>payoutId</code>, request refund for that slot.</td><td>Refund request rejected or message “instructor already paid out”.</td><td></td></tr></tbody></table><hr><h2 id="_5-refunds-student-request-→-admin-approve-reject" tabindex="-1">5. Refunds (student request → admin approve/reject) <a class="header-anchor" href="#_5-refunds-student-request-→-admin-approve-reject" aria-label="Permalink to &quot;5. Refunds (student request → admin approve/reject)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>5.1</td><td>Request refund (valid)</td><td><strong>Cancel</strong> a paid slot first. As <strong>Student</strong>, request refund for that slot.</td><td>Refund request created with status <strong>pending</strong>. Visible in Admin Refund Requests.</td><td></td></tr><tr><td>5.2</td><td>Admin approve refund</td><td>As <strong>Admin</strong>, open <strong>Refund Requests</strong>, approve the request.</td><td>Stripe: (1) transfer reversal (instructor share), (2) refund to student. Slot <code>paymentStatus</code> = <strong>refunded</strong>; RefundRequest status <strong>approved</strong>; transactions: student credit, instructor debit, platform commission reversal.</td><td></td></tr><tr><td>5.3</td><td>Admin reject refund</td><td>As <strong>Student</strong>, create another refund request. As <strong>Admin</strong>, <strong>reject</strong> it (optional: add reason).</td><td>RefundRequest status <strong>rejected</strong>; no Stripe refund/reversal; slot unchanged.</td><td></td></tr><tr><td>5.4</td><td>No refund before cancel</td><td>As <strong>Student</strong>, try to request refund for a slot that is <strong>not</strong> cancelled.</td><td>Error: “Refund can only be requested for a cancelled lesson”.</td><td></td></tr><tr><td>5.5</td><td>No double refund</td><td>After approving a refund, try to request refund again for same slot (or approve again).</td><td>Error or “already refunded”.</td><td></td></tr></tbody></table><hr><h2 id="_6-admin-–-payment-payout-visibility" tabindex="-1">6. Admin – Payment &amp; payout visibility <a class="header-anchor" href="#_6-admin-–-payment-payout-visibility" aria-label="Permalink to &quot;6. Admin – Payment &amp; payout visibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>6.1</td><td>Transactions list</td><td>As <strong>Admin</strong>, open <strong>Payments / Transactions</strong> (or Admin Transactions page).</td><td>List of transactions: payments, payouts, refunds, transfer_reversals with amount, type, role, date, Stripe IDs.</td><td></td></tr><tr><td>6.2</td><td>Transaction stats</td><td>On same page, check summary/cards (total payments, payouts, etc.).</td><td>Stats match data (or zero if none).</td><td></td></tr><tr><td>6.3</td><td>Filters</td><td>Use filters (date range, type, role) if available.</td><td>List updates correctly.</td><td></td></tr><tr><td>6.4</td><td>Refund requests list</td><td>As <strong>Admin</strong>, open <strong>Refund Requests</strong>.</td><td>Pending / approved / rejected list; can approve or reject.</td><td></td></tr></tbody></table><hr><h2 id="_7-edge-cases-cleanup" tabindex="-1">7. Edge cases &amp; cleanup <a class="header-anchor" href="#_7-edge-cases-cleanup" aria-label="Permalink to &quot;7. Edge cases &amp; cleanup&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Test</th><th>Steps</th><th>Expected</th><th>✓</th></tr></thead><tbody><tr><td>7.1</td><td>Abandoned checkout cleanup</td><td>Create a <strong>pending</strong> booking (deferred or instant), go to Stripe Checkout, <strong>close tab</strong> without completing. Leave booking <strong>pending</strong> and without <code>stripeCustomerId</code> for <strong>&gt;30 minutes</strong>. Wait for pending cleanup job (every 30 min).</td><td>Server log: <code>[PendingBookingCleanupJob] Done: cleaned=1</code>. Booking and slots <strong>cancelled</strong>; availability freed.</td><td></td></tr><tr><td>7.2</td><td>Resume pending booking</td><td>Create pending booking (deferred); leave without completing. Later, as <strong>Student</strong>, open “Booked lessons” / dashboard and find “Abandoned” or “Continue to checkout” for that booking. Click to resume.</td><td>Redirect to Stripe again (setup or payment); after completing, booking is confirmed.</td><td></td></tr><tr><td>7.3</td><td>Complete payment link (T-48 3DS)</td><td>For a slot in <strong>requires_action</strong>, open the “Complete payment” link (from email or dashboard) in a <strong>new tab</strong>.</td><td>Page loads with correct booking/slot; after completing 3DS, slot becomes paid.</td><td></td></tr><tr><td>7.4</td><td>Instructor without Stripe cannot be paid</td><td>Use an instructor who has no Stripe account. As <strong>Student</strong>, try to book.</td><td>Error or “not available for payment”.</td><td></td></tr><tr><td>7.5</td><td>Multiple slots one booking</td><td>Book <strong>multiple slots</strong> in one booking (instant). Pay once.</td><td>One charge; all slots <strong>paid</strong>; single PaymentIntent on booking.</td><td></td></tr><tr><td>7.6</td><td>Multiple slots one booking (deferred)</td><td>Book multiple slots in one booking (deferred). After T-48, each slot charged in turn.</td><td>Each slot gets its own charge when its T-48 time comes; per-slot PaymentIntent; all slots eventually paid.</td><td></td></tr></tbody></table><hr><h2 id="_8-server-logs-to-watch" tabindex="-1">8. Server logs to watch <a class="header-anchor" href="#_8-server-logs-to-watch" aria-label="Permalink to &quot;8. Server logs to watch&quot;">​</a></h2><p>While testing, keep an eye on the <strong>server console</strong>:</p><ul><li><code>[createBookingCheckoutSession]</code> → DEFERRED vs INSTANT</li><li><code>[T48ChargeJob]</code> → Tick, Charging slot..., payment succeeded / requires_action / payment_failed, Done. charged=...</li><li><code>[PayoutJob]</code> → Tick, Done. processed=...</li><li><code>[PendingBookingCleanupJob]</code> → Done: cleaned=...</li><li><code>[Stripe Webhook]</code> → checkout.session.completed, payment_intent.succeeded</li></ul><hr><h2 id="_9-quick-reference-–-what-to-test-per-flow" tabindex="-1">9. Quick reference – what to test per flow <a class="header-anchor" href="#_9-quick-reference-–-what-to-test-per-flow" aria-label="Permalink to &quot;9. Quick reference – what to test per flow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flow</th><th>Cards to use</th><th>What to verify</th></tr></thead><tbody><tr><td>Instant payment</td><td>4242…, 4000…3220 (3DS), 4000…0002 (decline)</td><td>Redirect, booking confirmed, slots paid, transactions</td></tr><tr><td>Deferred + T-48</td><td>4242… for setup; then T-48 charges 4242… or 3220 (3DS) or 0002 (fail)</td><td>Setup only; T-48 charges; requires_action + complete payment; payment_failed</td></tr><tr><td>Refund</td><td>After cancel slot → request → approve</td><td>Reversal + refund in Stripe; slot refunded; transactions</td></tr><tr><td>Payout</td><td>4000…0077 (immediate availability) or wait; mark completed; wait for job</td><td>Payout job creates payout; slot payoutStatus completed; transaction with stripePayoutId</td></tr></tbody></table><hr><h2 id="_10-sign-off-checklist-before-handover" tabindex="-1">10. Sign-off checklist (before handover) <a class="header-anchor" href="#_10-sign-off-checklist-before-handover" aria-label="Permalink to &quot;10. Sign-off checklist (before handover)&quot;">​</a></h2><ul><li>[ ] All items in sections 1–7 tested and ticked where applicable</li><li>[ ] No critical errors in server logs during normal flows</li><li>[ ] Stripe Dashboard (test mode): payments, Connect account balances, payouts look correct</li><li>[ ] Env and Stripe keys documented for client (test vs live)</li><li>[ ] Webhook URL for production documented (Dashboard endpoint + secret)</li><li>[ ] Any temporary changes (e.g. T-48 window, payout delay) reverted to production-ready values</li></ul><hr><h2 id="optional-production-deployment-checklist-for-client" tabindex="-1">Optional: production deployment checklist (for client) <a class="header-anchor" href="#optional-production-deployment-checklist-for-client" aria-label="Permalink to &quot;Optional: production deployment checklist (for client)&quot;">​</a></h2><ul><li>[ ] Replace test Stripe keys with live keys in production env</li><li>[ ] Create live webhook endpoint in Stripe Dashboard (HTTPS URL)</li><li>[ ] Subscribe to: <code>checkout.session.completed</code>, <code>payment_intent.succeeded</code>, and Connect events (account.updated, etc.)</li><li>[ ] Set <code>STRIPE_WEBHOOK_SECRET</code> to the <strong>live</strong> webhook signing secret</li><li>[ ] Set payout delay and T-48 interval to production values (e.g. 3 days payout delay, 5–15 min T-48 job)</li><li>[ ] Run through at least one full flow (booking → payment → complete lesson → payout) in live mode with a real card (small amount) if possible</li></ul><hr><p><strong>Document version:</strong> 1.0<br><strong>Use with:</strong> Local testing only (test Stripe keys). Do not use real card data in test mode.</p>',49)])])}const u=e(d,[["render",s]]);export{p as __pageData,u as default};
